const express = require('express');
const { jsPDF } = require('jspdf');
const router = express.Router();

const Reservation = require('../models/Reservation');
const Billet = require('../models/Billet');
const LigneSupplement = require('../models/LigneSupplement');
require('../models/Paiement');
const { protect, requireRole } = require('../middleware/auth');

const fs = require('fs');
const path = require('path');

// Logo embarqué en base64
const LOGO_B64 = 'data:image/jpeg;base64,';


const GREEN = [0, 103, 79];       // #00674F
const GREEN_LIGHT = [230, 245, 240];
const GRAY_LIGHT = [245, 245, 245];
const GRAY_TEXT = [100, 100, 100];
const BLACK = [30, 30, 30];
const WHITE = [255, 255, 255];

function fmtDate(d) {
  if (!d) return '—';
  try { return new Date(d).toLocaleDateString('fr-FR'); } catch { return '—'; }
}

function fmtMoney(n) {
  const num = typeof n === 'object' && n?.$numberDecimal ? parseFloat(n.$numberDecimal) : Number(n) || 0;
  // Formatage manuel pour éviter les caractères spéciaux (espaces insécables) qui
  // s'affichent en '/' dans certains rendus PDF
  const parts = Math.round(num).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ' ');
  return parts + ' FCFA';
}

function parseMontant(m) {
  if (!m) return 0;
  if (typeof m === 'number') return m;
  if (typeof m === 'string') return parseFloat(m) || 0;
  if (m.$numberDecimal) return parseFloat(m.$numberDecimal) || 0;
  return parseFloat(m.toString()) || 0;
}

/**
 * Dessine l'en-tête commun (logo + infos agence + numéro facture)
 */
function drawHeader(doc, factureNum, dateStr) {
  const W = doc.internal.pageSize.getWidth();

  // Bande verte en haut
  doc.setFillColor(...GREEN);
  doc.rect(0, 0, W, 2, 'F');

  // Logo
  try {
    doc.addImage(LOGO_B64, 'JPEG', 10, 6, 22, 22);
  } catch (e) { /* ignore */ }

  // Nom agence
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(16);
  doc.setTextColor(...GREEN);
  doc.text('KYSWA TRAVEL', 36, 14);

  // Sous-titre agence
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(7.5);
  doc.setTextColor(...GRAY_TEXT);
  doc.text('Agence de voyages | Oumra · Hajj · Ziarra · Billets', 36, 19);
  doc.text('+221 77 661 71 71  ·  +221 76 160 22 22  ·  +221 77 461 12 52', 36, 23.5);
  doc.text('kyswainc@outlook.fr  ·  Centre commercial Keur Khad m, Dakar', 36, 28);

  // Numéro facture (droite)
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(9);
  doc.setTextColor(...BLACK);
  doc.text(`N° ${factureNum}`, W - 14, 14, { align: 'right' });
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(8.5);
  doc.setTextColor(...GRAY_TEXT);
  doc.text(`Date : ${dateStr}`, W - 14, 19, { align: 'right' });

  // Ligne séparatrice verte
  doc.setDrawColor(...GREEN);
  doc.setLineWidth(0.8);
  doc.line(10, 34, W - 10, 34);

  return 38; // y après header
}

/**
 * Dessine le pied de page
 */
function drawFooter(doc) {
  const W = doc.internal.pageSize.getWidth();
  const H = doc.internal.pageSize.getHeight();
  doc.setFillColor(...GREEN);
  doc.rect(0, H - 10, W, 10, 'F');
  doc.setFont('helvetica', 'italic');
  doc.setFontSize(8);
  doc.setTextColor(...WHITE);
  doc.text('Kyswa Travel  —  Ce document tient lieu de reçu officiel', W / 2, H - 4, { align: 'center' });
}

/**
 * Page 2 : Conditions générales d'inscription
 */
function addConditionsPage(doc, clientNom, factureNum) {
  doc.addPage();
  const W = doc.internal.pageSize.getWidth();
  let y = drawHeader(doc, factureNum, fmtDate(new Date()));

  // Titre
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(13);
  doc.setTextColor(...GREEN);
  doc.text('CONDITIONS GENERALES D\'INSCRIPTION', W / 2, y + 8, { align: 'center' });
  doc.setDrawColor(...GREEN);
  doc.setLineWidth(0.5);
  doc.line(30, y + 11, W - 30, y + 11);
  y += 20;

  doc.setFont('helvetica', 'italic');
  doc.setFontSize(8.5);
  doc.setTextColor(...GRAY_TEXT);
  doc.text('La presente facture constitue un contrat entre l\'agence KYSWA TRAVEL et le client pour les prestations de voyage.', 14, y);
  y += 10;

  const conditions = [
    ['1. RESERVATION ET PAIEMENT',
      'La reservation est confirmee apres versement d\'un acompte de 30%. Le solde doit etre regle au plus tard 1 mois avant la date de depart.'],
    ['2. ANNULATION',
      'Toute annulation doit etre notifiee par ecrit au moins 2 mois avant le depart. Des frais de dossier sont retenus et le remboursement ne sera jamais integral. Des frais peuvent etre exiges avant certaines demarches (billets, visas, etc.).'],
    ['3. REMBOURSEMENT',
      'La procedure de remboursement debute apres le retour des passagers, environ 2 mois apres la date de retour prevue. Aucun remboursement en especes ne sera effectue. Un pourcentage est systematiquement deduit du montant paye.'],
    ['4. OFFRES PROMOTIONNELLES',
      'Les packages PROMO ne sont en aucun cas remboursables. Le client peut soit ceder sa place a un proche, soit passer a un package standard en reglant la difference de prix.'],
    ['5. RESPONSABILITE',
      'L\'agence KYSWA TRAVEL ne saurait etre tenue responsable des retards, annulations ou modifications imposes par les compagnies aeriennes, les ambassades ou tout cas de force majeure. Le client est seul responsable de la validite de ses documents de voyage (passeport, visa, vaccins obligatoires).'],
    ['6. ACCEPTATION',
      'La signature de la presente facture vaut acceptation pleine et entiere de l\'ensemble des conditions generales ci-dessus.'],
  ];

  conditions.forEach(([titre, texte], idx) => {
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(8.5);
    doc.setTextColor(...BLACK);
    doc.text(titre + ' :', 14, y);
    y += 5;
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(8);
    doc.setTextColor(...GRAY_TEXT);
    const lines = doc.splitTextToSize(texte, W - 28);
    doc.text(lines, 14, y);
    y += lines.length * 4.5 + 3;
  });

  y += 8;

  // Zone signatures
  const colW = (W - 28) / 2;
  const col1X = 14;
  const col2X = 14 + colW + 14;

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(9);
  doc.setTextColor(...GREEN);
  doc.text('Signature & Cachet Comptable', col1X + colW / 2, y, { align: 'center' });
  doc.text('Signature Client', col2X + colW / 2, y, { align: 'center' });
  y += 4;

  doc.setDrawColor(...GRAY_TEXT);
  doc.setLineWidth(0.3);
  doc.rect(col1X, y, colW, 30);
  doc.rect(col2X, y, colW, 30);

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(8);
  doc.setTextColor(...GRAY_TEXT);
  doc.text(clientNom || '', col2X + colW / 2, y + 34, { align: 'center' });

  drawFooter(doc);
}

// ─────────────────────────────────────────────────────────────────────────────
// GET /api/factures/reservation/:id
// ─────────────────────────────────────────────────────────────────────────────
router.get('/reservation/:id', protect, requireRole('commercial', 'comptable', 'administrateur', 'dg', 'secretaire', 'oumra'), async (req, res) => {
  try {
    const reservation = await Reservation.findById(req.params.id)
      .populate('clients')
      .populate('packageKId')
      .populate('paiements');

    if (!reservation) return res.status(404).json({ message: 'Réservation introuvable' });

    const lignesSupp = await LigneSupplement.find({ reservationId: reservation._id })
      .populate('supplementId').populate('clientId', 'nom prenom');

    const montantTotal = Number(reservation.montantTotalDu || 0);
    const totalPaye = (reservation.paiements || []).reduce((s, p) => s + parseMontant(p.montant), 0);
    const reste = montantTotal - totalPaye;

    const factureNum = `FAC-${reservation.numero || reservation.idReservation || reservation._id.toString().slice(-6)}`;
    const dateStr = fmtDate(new Date());
    const clientPrincipal = reservation.clients?.[0];
    const clientNom = clientPrincipal ? `${clientPrincipal.nom} ${clientPrincipal.prenom}` : '—';
    const pkg = reservation.packageKId || {};

    const doc = new jsPDF({ unit: 'mm', format: 'a4' });
    const W = doc.internal.pageSize.getWidth();

    // ── PAGE 1 : FACTURE ──────────────────────────────────────────────────────
    let y = drawHeader(doc, factureNum, dateStr);

    // Titre FACTURE
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(14);
    doc.setTextColor(...GREEN);
    doc.text('FACTURE', W / 2, y + 6, { align: 'center' });
    doc.setDrawColor(...GREEN);
    doc.setLineWidth(0.5);
    doc.line(60, y + 9, W - 60, y + 9);
    y += 16;

    // Blocs CLIENT + VOYAGE côte à côte
    const blockW = (W - 34) / 2;
    const block1X = 14;
    const block2X = 14 + blockW + 6;

    // Bloc CLIENT
    doc.setFillColor(...GRAY_LIGHT);
    doc.rect(block1X, y, blockW, 38, 'F');
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(8.5);
    doc.setTextColor(...GREEN);
    doc.text('CLIENT', block1X + 4, y + 6);
    doc.setDrawColor(...GREEN);
    doc.setLineWidth(0.4);
    doc.line(block1X + 4, y + 7.5, block1X + 22, y + 7.5);

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(8.5);
    doc.setTextColor(...BLACK);
    let cy = y + 13;
    (reservation.clients || []).forEach((c, i) => {
      if (i === 0) {
        doc.text(`Nom : ${c.nom || '—'}`, block1X + 4, cy); cy += 5;
        doc.text(`Prénom : ${c.prenom || '—'}`, block1X + 4, cy); cy += 5;
        doc.text(`Tél : ${c.telephone || '—'}`, block1X + 4, cy); cy += 5;
        doc.text(`Passeport : ${c.numeroPasseport || '—'}`, block1X + 4, cy);
      }
    });

    // Bloc VOYAGE
    doc.setFillColor(...GRAY_LIGHT);
    doc.rect(block2X, y, blockW, 38, 'F');
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(8.5);
    doc.setTextColor(...GREEN);
    doc.text('VOYAGE', block2X + 4, y + 6);
    doc.setDrawColor(...GREEN);
    doc.setLineWidth(0.4);
    doc.line(block2X + 4, y + 7.5, block2X + 22, y + 7.5);

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(8.5);
    doc.setTextColor(...BLACK);
    let vy = y + 13;
    doc.text(`${pkg.nomReference || '—'}`, block2X + 4, vy); vy += 5;
    doc.text(`Service : ${pkg.type || '—'}`, block2X + 4, vy); vy += 5;
    doc.text(`Départ : ${fmtDate(reservation.dateDepart) || '—'}`, block2X + 4, vy); vy += 5;
    doc.text(`Retour : ${fmtDate(reservation.dateRetour) || '—'}`, block2X + 4, vy);

    y += 44;

    // Chambre / Formule / Réf
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(8.5);
    doc.setTextColor(...GRAY_TEXT);
    doc.text(`Chambre : ${reservation.typeChambre || '—'}`, 14, y);
    doc.text(`Formule : ${reservation.formule || 'Standard'}`, 14, y + 5);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(...BLACK);
    doc.text(`Réf : ${reservation.numero || reservation.idReservation || '—'}`, W - 14, y, { align: 'right' });
    y += 14;

    // Tableau paiements
    const paiementsRows = (reservation.paiements || []).map((p, i) => [
      String(i + 1),
      fmtDate(p.dateReglement),
      p.mode || '—',
      p.reference || '—',
      fmtMoney(parseMontant(p.montant)),
    ]);

    if (paiementsRows.length === 0) {
      paiementsRows.push(['—', '—', '—', '—', '0 FCFA']);
    }

    // En-tête tableau vert
    const colWidths = [10, 30, 30, 50, 40];
    const tableX = 14;
    const rowH = 7;
    const headers = ['N°', 'Date', 'Mode', 'Reçu', 'Montant'];

    doc.setFillColor(...GREEN);
    doc.rect(tableX, y, W - 28, rowH, 'F');
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(8.5);
    doc.setTextColor(...WHITE);
    let cx = tableX + 3;
    headers.forEach((h, i) => {
      const align = i === headers.length - 1 ? 'right' : 'left';
      const tx = align === 'right' ? tableX + colWidths.slice(0, i + 1).reduce((a, b) => a + b, 0) - 3 : cx;
      doc.text(h, tx, y + 5, { align });
      cx += colWidths[i];
    });
    y += rowH;

    // Lignes tableau
    paiementsRows.forEach((row, ri) => {
      doc.setFillColor(ri % 2 === 0 ? 255 : 248, ri % 2 === 0 ? 255 : 250, ri % 2 === 0 ? 255 : 248);
      doc.rect(tableX, y, W - 28, rowH, 'F');
      doc.setFont('helvetica', 'normal');
      doc.setFontSize(8.5);
      doc.setTextColor(...BLACK);
      let cx2 = tableX + 3;
      row.forEach((cell, ci) => {
        const isLast = ci === row.length - 1;
        const tx = isLast ? tableX + colWidths.slice(0, ci + 1).reduce((a, b) => a + b, 0) - 3 : cx2;
        doc.text(String(cell), tx, y + 5, { align: isLast ? 'right' : 'left' });
        cx2 += colWidths[ci];
      });
      // Bordure basse légère
      doc.setDrawColor(220, 220, 220);
      doc.setLineWidth(0.2);
      doc.line(tableX, y + rowH, tableX + W - 28, y + rowH);
      y += rowH;
    });

    y += 10;

    // Totaux (alignés à droite)
    const totalsX = W - 80;
    const totalsW = 66;

    const drawTotalLine = (label, value, bold = false, color = BLACK) => {
      doc.setFont('helvetica', bold ? 'bold' : 'normal');
      doc.setFontSize(bold ? 9.5 : 8.5);
      doc.setTextColor(...GRAY_TEXT);
      doc.text(label, totalsX, y);
      doc.setTextColor(...color);
      doc.text(value, totalsX + totalsW, y, { align: 'right' });
      if (bold) {
        doc.setDrawColor(...GREEN);
        doc.setLineWidth(0.4);
        doc.line(totalsX, y + 1.5, totalsX + totalsW, y + 1.5);
      }
      y += bold ? 8 : 6;
    };

    drawTotalLine('Prix total :', fmtMoney(montantTotal));
    drawTotalLine('Montant versé :', fmtMoney(totalPaye), false, [22, 163, 74]);
    drawTotalLine('Solde restant :', fmtMoney(reste), true, reste <= 0 ? [22, 163, 74] : [220, 38, 38]);

    // Tableau suppléments si présents
    if (lignesSupp && lignesSupp.length > 0) {
      y += 10;

      // Titre
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(9);
      doc.setTextColor(...GREEN);
      doc.text('Suppléments :', 14, y);
      y += 5;

      // En-tête tableau vert
      const suppColW = [60, 30, 20, 30, 36];
      const suppHeaders = ['Désignation', 'Client', 'Qté', 'Prix unitaire', 'Total'];
      const suppRowH = 7;

      doc.setFillColor(...GREEN);
      doc.rect(14, y, W - 28, suppRowH, 'F');
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(8);
      doc.setTextColor(...WHITE);
      let scx = 17;
      suppHeaders.forEach((h, i) => {
        const isLast = i === suppHeaders.length - 1;
        const tx = isLast ? 14 + suppColW.slice(0, i + 1).reduce((a, b) => a + b, 0) - 3 : scx;
        doc.text(h, tx, y + 5, { align: isLast ? 'right' : 'left' });
        scx += suppColW[i];
      });
      y += suppRowH;

      // Lignes
      lignesSupp.forEach((ls, ri) => {
        doc.setFillColor(ri % 2 === 0 ? 255 : 248, ri % 2 === 0 ? 255 : 250, ri % 2 === 0 ? 255 : 248);
        doc.rect(14, y, W - 28, suppRowH, 'F');
        doc.setFont('helvetica', 'normal');
        doc.setFontSize(8);
        doc.setTextColor(...BLACK);

        const nom = ls.supplementId?.nom || 'Supplément';
        const client = ls.clientId ? `${ls.clientId.nom} ${ls.clientId.prenom}` : '—';
        const qte = String(ls.quantite || 1);
        const pu = fmtMoney(ls.prixUnitaire || 0);
        const total = fmtMoney((ls.prixUnitaire || 0) * (ls.quantite || 1));

        const suppRow = [nom, client, qte, pu, total];
        let scx2 = 17;
        suppRow.forEach((cell, ci) => {
          const isLast = ci === suppRow.length - 1;
          const tx = isLast ? 14 + suppColW.slice(0, ci + 1).reduce((a, b) => a + b, 0) - 3 : scx2;
          doc.text(String(cell), tx, y + 5, { align: isLast ? 'right' : 'left' });
          scx2 += suppColW[ci];
        });

        doc.setDrawColor(220, 220, 220);
        doc.setLineWidth(0.2);
        doc.line(14, y + suppRowH, 14 + W - 28, y + suppRowH);
        y += suppRowH;
      });
    }

    drawFooter(doc);

    // ── PAGE 2 : CONDITIONS GÉNÉRALES ─────────────────────────────────────────
    addConditionsPage(doc, clientNom, factureNum);

    const buffer = Buffer.from(doc.output('arraybuffer'));
    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader('Content-Disposition', `attachment; filename="facture-${factureNum}.pdf"`);
    return res.send(buffer);

  } catch (err) {
    console.error('Erreur génération facture réservation:', err);
    return res.status(500).json({ message: 'Erreur lors de la génération de la facture' });
  }
});

// ─────────────────────────────────────────────────────────────────────────────
// GET /api/factures/billet/:id
// ─────────────────────────────────────────────────────────────────────────────
router.get('/billet/:id', protect, requireRole('commercial', 'comptable', 'administrateur', 'dg', 'secretaire', 'oumra'), async (req, res) => {
  try {
    const billet = await Billet.findById(req.params.id).populate('clientId').populate('paiements');
    if (!billet) return res.status(404).json({ message: 'Billet introuvable' });

    const montantTotal = Number(billet.prix || 0);
    const totalPaye = (billet.paiements || []).reduce((s, p) => s + parseMontant(p.montant), 0);
    const reste = montantTotal - totalPaye;

    const factureNum = `FAC-BIL-${billet.numeroBillet || billet._id.toString().slice(-6)}`;
    const dateStr = fmtDate(new Date());
    const c = billet.clientId || {};
    const clientNom = `${c.nom || ''} ${c.prenom || ''}`.trim() || '—';

    const doc = new jsPDF({ unit: 'mm', format: 'a4' });
    const W = doc.internal.pageSize.getWidth();

    // ── PAGE 1 : FACTURE ──────────────────────────────────────────────────────
    let y = drawHeader(doc, factureNum, dateStr);

    // Titre
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(14);
    doc.setTextColor(...GREEN);
    doc.text('FACTURE', W / 2, y + 6, { align: 'center' });
    doc.setDrawColor(...GREEN);
    doc.setLineWidth(0.5);
    doc.line(60, y + 9, W - 60, y + 9);
    y += 16;

    // Blocs CLIENT + BILLET
    const blockW = (W - 34) / 2;
    const block1X = 14;
    const block2X = 14 + blockW + 6;

    doc.setFillColor(...GRAY_LIGHT);
    doc.rect(block1X, y, blockW, 38, 'F');
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(8.5);
    doc.setTextColor(...GREEN);
    doc.text('CLIENT', block1X + 4, y + 6);
    doc.setDrawColor(...GREEN);
    doc.setLineWidth(0.4);
    doc.line(block1X + 4, y + 7.5, block1X + 22, y + 7.5);
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(8.5);
    doc.setTextColor(...BLACK);
    let cy = y + 13;
    doc.text(`Nom : ${c.nom || '—'}`, block1X + 4, cy); cy += 5;
    doc.text(`Prénom : ${c.prenom || '—'}`, block1X + 4, cy); cy += 5;
    doc.text(`Tél : ${c.telephone || '—'}`, block1X + 4, cy); cy += 5;
    doc.text(`Passeport : ${c.numeroPasseport || '—'}`, block1X + 4, cy);

    doc.setFillColor(...GRAY_LIGHT);
    doc.rect(block2X, y, blockW, 38, 'F');
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(8.5);
    doc.setTextColor(...GREEN);
    doc.text('BILLET', block2X + 4, y + 6);
    doc.setDrawColor(...GREEN);
    doc.setLineWidth(0.4);
    doc.line(block2X + 4, y + 7.5, block2X + 22, y + 7.5);
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(8.5);
    doc.setTextColor(...BLACK);
    let vy = y + 13;
    doc.text(`N° : ${billet.numeroBillet || '—'}`, block2X + 4, vy); vy += 5;
    doc.text(`Compagnie : ${billet.compagnie || '—'}`, block2X + 4, vy); vy += 5;
    doc.text(`Départ : ${fmtDate(billet.dateDepart)}`, block2X + 4, vy); vy += 5;
    doc.text(`Destination : ${billet.destination || '—'}`, block2X + 4, vy);

    y += 44;

    // Tableau paiements
    const paiementsRows = (billet.paiements || []).map((p, i) => [
      String(i + 1),
      fmtDate(p.dateReglement),
      p.mode || '—',
      p.reference || '—',
      fmtMoney(parseMontant(p.montant)),
    ]);
    if (paiementsRows.length === 0) paiementsRows.push(['—', '—', '—', '—', '0 FCFA']);

    const colWidths = [10, 30, 30, 50, 40];
    const tableX = 14;
    const rowH = 7;
    const headers = ['N°', 'Date', 'Mode', 'Reçu', 'Montant'];

    doc.setFillColor(...GREEN);
    doc.rect(tableX, y, W - 28, rowH, 'F');
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(8.5);
    doc.setTextColor(...WHITE);
    let cx = tableX + 3;
    headers.forEach((h, i) => {
      const align = i === headers.length - 1 ? 'right' : 'left';
      const tx = align === 'right' ? tableX + colWidths.slice(0, i + 1).reduce((a, b) => a + b, 0) - 3 : cx;
      doc.text(h, tx, y + 5, { align });
      cx += colWidths[i];
    });
    y += rowH;

    paiementsRows.forEach((row, ri) => {
      doc.setFillColor(ri % 2 === 0 ? 255 : 248, ri % 2 === 0 ? 255 : 250, ri % 2 === 0 ? 255 : 248);
      doc.rect(tableX, y, W - 28, rowH, 'F');
      doc.setFont('helvetica', 'normal');
      doc.setFontSize(8.5);
      doc.setTextColor(...BLACK);
      let cx2 = tableX + 3;
      row.forEach((cell, ci) => {
        const isLast = ci === row.length - 1;
        const tx = isLast ? tableX + colWidths.slice(0, ci + 1).reduce((a, b) => a + b, 0) - 3 : cx2;
        doc.text(String(cell), tx, y + 5, { align: isLast ? 'right' : 'left' });
        cx2 += colWidths[ci];
      });
      doc.setDrawColor(220, 220, 220);
      doc.setLineWidth(0.2);
      doc.line(tableX, y + rowH, tableX + W - 28, y + rowH);
      y += rowH;
    });

    y += 10;

    const totalsX = W - 80;
    const totalsW = 66;
    const drawTotalLine = (label, value, bold = false, color = BLACK) => {
      doc.setFont('helvetica', bold ? 'bold' : 'normal');
      doc.setFontSize(bold ? 9.5 : 8.5);
      doc.setTextColor(...GRAY_TEXT);
      doc.text(label, totalsX, y);
      doc.setTextColor(...color);
      doc.text(value, totalsX + totalsW, y, { align: 'right' });
      if (bold) {
        doc.setDrawColor(...GREEN);
        doc.setLineWidth(0.4);
        doc.line(totalsX, y + 1.5, totalsX + totalsW, y + 1.5);
      }
      y += bold ? 8 : 6;
    };

    drawTotalLine('Prix total :', fmtMoney(montantTotal));
    drawTotalLine('Montant versé :', fmtMoney(totalPaye), false, [22, 163, 74]);
    drawTotalLine('Solde restant :', fmtMoney(reste), true, reste <= 0 ? [22, 163, 74] : [220, 38, 38]);

    drawFooter(doc);

    // ── PAGE 2 : CONDITIONS GÉNÉRALES ─────────────────────────────────────────
    addConditionsPage(doc, clientNom, factureNum);

    const buffer = Buffer.from(doc.output('arraybuffer'));
    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader('Content-Disposition', `attachment; filename="facture-${factureNum}.pdf"`);
    return res.send(buffer);

  } catch (err) {
    console.error('Erreur génération facture billet:', err);
    return res.status(500).json({ message: 'Erreur lors de la génération de la facture' });
  }
});

module.exports = router;
